text:
.account-hub-protocol-select-card {
  position: relative;
  display: block;
  inline-size: 148px;
  block-size: 127px;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 1, 2, 0.1);
  border-radius: 8px;
  user-select: none;

  &:has(input:checked) {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.14);
  }

  & input[type="radio"] {
    position: absolute;
    inset: 0;
    z-index: 1;
    inline-size: 100%;
    block-size: 100%;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }

  & .account-hub-protocol-select-card-content {
    display: grid;
    grid-template-rows: 56px 69px;
    box-sizing: border-box;
    block-size: 100%;
    overflow: hidden;
    border: 1px solid var(--color-primary-default);
    border-radius: 8px;
    pointer-events: none;
  }
